// @ts-nocheck -- type-checked in the motion-film project, not here.
// Generated by scripts/sync-film.mjs from motion-film/src/film/timeline.ts. Edit it there, then run `npm run sync:film`.
/*
 * The film's running order. Durations are in frames at 30 fps; transition frames overlap the
 * neighbouring scenes. When the music arrives, these numbers get snapped to its bars.
 */
export type SceneId =
  | "opening"
  | "ganesh"
  | "couple"
  | "family"
  | "engagement"
  | "haldiMehendi"
  | "sangeet"
  | "dayTitle"
  | "sehra"
  | "baraat"
  | "jaimaal"
  | "lunch"
  | "phere"
  | "vidai"
  | "reception"
  | "finale"
  | "credits";

export type TransitionKind = "iris" | "curtain" | "floral" | "card" | "push" | "fade";

export type Beat = { scene: SceneId; dur: number; solo?: boolean; transitionIn?: { kind: TransitionKind; dur: number } };

/**
 * Each scene = its build-up + a HOLD of at least ~2.5 s once the last text has landed
 * (before the ~1 s outgoing transition), so every detail can be read comfortably on a phone.
 */
export const DURATIONS: Record<SceneId, number> = {
  opening: 260,
  ganesh: 170,
  couple: 290,
  family: 470,
  engagement: 270,
  haldiMehendi: 300,
  sangeet: 300,
  dayTitle: 130,
  sehra: 210,
  baraat: 240,
  jaimaal: 210,
  lunch: 170,
  phere: 310,
  vidai: 270,
  reception: 270,
  finale: 320,
  credits: 660, // ~40 names: each needs time to be read as it rolls
};
export const SOLO_DURATION = 400;

const T = (kind: TransitionKind, dur: number) => ({ kind, dur });
const beat = (scene: SceneId, transitionIn?: Beat["transitionIn"], solo?: boolean): Beat => ({
  scene,
  dur: solo ? SOLO_DURATION : DURATIONS[scene],
  solo,
  transitionIn,
});

const intro: Beat[] = [
  beat("opening"),
  beat("ganesh", T("iris", 26)),
  beat("couple", T("curtain", 40)),
  beat("family", T("card", 26)),
];
const outro: Beat[] = [beat("finale", T("floral", 32)), beat("credits", T("card", 26))];

export type VersionId = "full" | "engagement" | "reception";

/*
 * Music grid: 100 BPM at 30 fps ⇒ one beat = 18 frames, one bar = 72 frames.
 * Every cut (the midpoint of a transition) is snapped forward onto the grid by lengthening the
 * previous scene's hold — never shortening it. Drops land on a full bar.
 */
export const FRAMES_PER_BEAT = 18;
export const FRAMES_PER_BAR = 72;
const BAR_ALIGNED: ReadonlySet<SceneId> = new Set<SceneId>(["sangeet", "baraat", "finale", "haldiMehendi", "reception"]);

const snapToMusic = (beats: Beat[]): Beat[] => {
  const out = beats.map((b) => ({ ...b }));
  let start = 0;
  for (let i = 1; i < out.length; i++) {
    const t = out[i].transitionIn?.dur ?? 0;
    const cut = start + out[i - 1].dur - t + t / 2;
    const grid = BAR_ALIGNED.has(out[i].scene) ? FRAMES_PER_BAR : FRAMES_PER_BEAT;
    out[i - 1].dur += Math.ceil(cut / grid) * grid - cut;
    start += out[i - 1].dur - t;
  }
  // Let the last scene end on a bar line too, so the final chord rings out cleanly.
  const end = start + out[out.length - 1].dur;
  out[out.length - 1].dur += Math.ceil(end / FRAMES_PER_BAR) * FRAMES_PER_BAR - end;
  return out;
};

const RAW: Record<VersionId, Beat[]> = {
  full: [
    ...intro,
    beat("engagement", T("floral", 32)),
    beat("haldiMehendi", T("iris", 26)),
    beat("sangeet", T("curtain", 40)),
    beat("dayTitle", T("fade", 22)),
    beat("sehra", T("floral", 28)),
    beat("baraat", T("push", 26)),
    beat("jaimaal", T("floral", 28)),
    beat("lunch", T("card", 22)),
    beat("phere", T("iris", 28)),
    beat("vidai", T("fade", 32)),
    beat("reception", T("iris", 30)),
    ...outro,
  ],
  engagement: [...intro, beat("engagement", T("floral", 32), true), ...outro],
  reception: [...intro, beat("reception", T("floral", 32), true), ...outro],
};

export const VERSIONS: Record<VersionId, Beat[]> = {
  full: snapToMusic(RAW.full),
  engagement: snapToMusic(RAW.engagement),
  reception: snapToMusic(RAW.reception),
};

export const versionLength = (v: VersionId): number =>
  VERSIONS[v].reduce((sum, b) => sum + b.dur - (b.transitionIn?.dur ?? 0), 0);

/** Where each scene sits in the film: start frame, length, and the cut (transition midpoint) into it. */
export type Placement = Beat & { start: number; cut: number };
export const placements = (v: VersionId): Placement[] => {
  let start = 0;
  return VERSIONS[v].map((b, i) => {
    const t = b.transitionIn?.dur ?? 0;
    if (i > 0) start -= t;
    const p = { ...b, start, cut: i === 0 ? 0 : start + t / 2 };
    start += b.dur;
    return p;
  });
};
